// Visual feedback follows acknowledged game state; it never chooses outcomes.
const euro=n=>'€'+Math.abs(n).toLocaleString('ja-JP');
const pipPositions={1:[5],2:[1,9],3:[1,5,9],4:[1,3,7,9],5:[1,3,5,7,9],6:[1,3,4,6,7,9]};
const cardLine=/^(旅の写真|交通券を|旅程を|手続き確認|案内人から|景観整備|三歩戻|観光ガイド|旅先から|荷物の修理|次の旅は|忘れ物の手続き|旅人仲間|資料の寄付|三歩前|旅の記録)/;
function additions(previous,next){for(let n=Math.min(previous.length,next.length);n>=0;n--)if(previous.slice(-n||previous.length).join('\n')===next.slice(0,n).join('\n'))return next.slice(n);return next;}
export class JourneyEffects{
 constructor({sound=null,board=[]}={}){this.sound=sound;this.board=board;this.queue=[];this.holding=false;this.displayState=null;this.busyUntil=0;this.onReady=()=>{};this.previous=null;this.pending=false;this.timers=[];this.flights=new Map();this.transients=new Set();this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.layer=document.createElement('div');this.layer.className='journey-effects';this.layer.setAttribute('aria-live','polite');this.layer.setAttribute('aria-atomic','false');document.getElementById('game').append(this.layer);}
 later(fn,ms){const id=setTimeout(()=>{this.timers=this.timers.filter(x=>x!==id);fn();},ms);this.timers.push(id);return id;}
 reset(){this.queue=[];this.holding=false;this.displayState=null;this.receipt?.remove();this.receipt=null;this.busyUntil=0;this.stage?.remove();this.stage=null;this.previous=null;this.pending=false;this.timers.forEach(clearTimeout);this.timers=[];this.layer.replaceChildren();for(const node of this.flights.values())node.remove();this.flights.clear();for(const node of this.transients)node.remove();this.transients.clear();clearInterval(this.spin);this.drawDice([0,0]);}
 drawDice(values,rolling=false){const box=document.getElementById('dice');box.replaceChildren();box.classList.toggle('rolling',rolling);box.setAttribute('aria-label',rolling?'サイコロを振っています':values.every(Boolean)?`サイコロ ${values.join(' と ')}、合計 ${values[0]+values[1]}`:'サイコロを振って出発');const pair=document.createElement('span');pair.className='dice-pair';for(const value of values){const die=document.createElement('span');die.className='die';die.dataset.value=value;die.setAttribute('aria-hidden','true');for(let n=1;n<=9;n++){const pip=document.createElement('i');pip.className='die-pip';pip.style.opacity=pipPositions[value]?.includes(n)?'1':'0';die.append(pip);}pair.append(die);}box.append(pair);const caption=document.createElement('small');caption.textContent=rolling?'ROLLING…':values.every(Boolean)?`${values[0]} + ${values[1]} = ${values[0]+values[1]}`:'YOUR JOURNEY STARTS HERE';box.append(caption);}
 get short(){return this.reduced.matches||this.sound?.settings.quick===true;}
 get busy(){return this.holding||Date.now()<this.busyUntil;}
 showStage(){this.stage?.remove();if(this.short)return;const stage=document.createElement('div');stage.className='dice-stage tumbling';stage.setAttribute('aria-label','サイコロの演出');const tray=document.createElement('div');tray.className='dice-tray';const label=document.createElement('p');label.className='dice-stage-label';label.textContent='ROLL THE WORLD';const pair=document.createElement('div');pair.className='cube-pair';for(let d=0;d<2;d++){const cube=document.createElement('div');cube.className='dice-cube';cube.setAttribute('aria-hidden','true');for(let face=1;face<=6;face++){const panel=document.createElement('span');panel.className='cube-face face-'+face;for(let pip=1;pip<=9;pip++){const point=document.createElement('i');point.className='cube-pip';point.style.visibility=pipPositions[face].includes(pip)?'visible':'hidden';panel.append(point);}cube.append(panel);}pair.append(cube);}const result=document.createElement('p');result.className='dice-result';result.textContent='サイコロが転がっています…';const close=document.createElement('button');close.className='tray-close';close.textContent='盤面を見る';close.onclick=()=>stage.remove();tray.append(label,pair,result,close);stage.append(tray);document.body.append(stage);this.stage=stage;}
 settleStage(dice){const stage=this.stage;if(!stage)return;stage.classList.remove('tumbling');stage.classList.add('settled');const rotations={1:'rotateX(0deg) rotateY(0deg)',2:'rotateX(0deg) rotateY(-90deg)',3:'rotateX(-90deg) rotateY(0deg)',4:'rotateX(90deg) rotateY(0deg)',5:'rotateX(0deg) rotateY(90deg)',6:'rotateX(0deg) rotateY(180deg)'};stage.querySelectorAll('.dice-cube').forEach((cube,i)=>cube.style.transform=rotations[dice[i]]);stage.querySelector('.dice-result').textContent=`${dice[0]} + ${dice[1]} = ${dice[0]+dice[1]}`+(dice[0]===dice[1]?' · ゾロ目！':'');}
 celebrate(title,text,kind){this.sound?.play(kind);this.layer.querySelector('.collection-stamp')?.remove();const card=document.createElement('div');card.className='collection-stamp';card.setAttribute('role','status');const head=document.createElement('strong'),body=document.createElement('span');head.textContent=title;body.textContent=text;card.append(head,body);this.layer.append(card);this.later(()=>card.remove(),3500);}
 milestones(prev,state){for(const tile of this.board){const old=prev.properties?.[tile.id],now=state.properties?.[tile.id];if(!old||!now)continue;const owner=state.players.find(p=>p.id===now.owner);if(!owner)continue;if(now.owner!==old.owner){const group=tile.group?this.board.filter(t=>t.group===tile.group):[];const complete=group.length&&group.every(t=>state.properties[t.id]?.owner===now.owner);this.celebrate(complete?'COLOR SET COMPLETE':'新しい旅の拠点',owner.name+' · '+tile.name+(complete?' — 同じ色がそろいました':' を獲得'),complete?'complete':'purchase');}else if(now.houses>old.houses)this.celebrate(now.houses===5?'ホテル完成':'街が育ちました',tile.name+' · '+(now.houses===5?'ホテル':`家${now.houses}軒`),'build');}if(state.phase==='over'&&prev.phase!=='over')this.celebrate('旅のチャンピオン',state.players.find(p=>p.id===state.winner)?.name||'旅の終了','victory');else if(state.turn!==prev.turn)this.sound?.play('turn');}
 startRoll(){if(this.pending)return false;this.pending=true;this.spinDice();this.showStage();this.sound?.play(this.short?'land':'roll');return true;}
 spinDice(){clearInterval(this.spin);let frame=0;this.drawDice([1,6],!this.short);if(!this.short)this.spin=setInterval(()=>{frame++;this.drawDice([frame%6+1,(frame*3+2)%6+1],true);},85);}
 cancelPending(){if(!this.pending)return;this.pending=false;clearInterval(this.spin);this.spin=null;this.stage?.remove();this.stage=null;this.drawDice(this.previous?.dice||[0,0]);}
 observe(state){
 if(!state)return;
 const latest=this.queue.at(-1)||this.previous;
 if(latest&&state.revision<=latest.revision)return;
 if(this.busy){this.queue.push(structuredClone(state));return;}
 this.present(state);
 }
 finish(){this.holding=false;this.busyUntil=0;const next=this.queue.shift();if(next)this.present(next);this.onReady();}
 present(state){
 const prev=this.previous;this.previous=structuredClone(state);
 if(!prev){this.displayState=state;this.drawDice(state.dice);return;}
 const logs=additions(prev.log,state.log),rolled=logs.some(x=>x.includes(' のサイコロ: '));
 const events=Array.isArray(state.cardEvents)?state.cardEvents:logs.filter(x=>cardLine.test(x)).map(text=>({text,type:'chance'}));
 const changes=state.players.flatMap(p=>{const old=prev.players.find(x=>x.id===p.id);return old&&p.money!==old.money?[{player:p,before:old.money,delta:p.money-old.money}]:[]});
 // Hold the previous public view for an unopened card: no balance, log or inventory spoilers.
 this.displayState=events.length?prev:structuredClone(state);
 if(!events.length)for(const p of this.displayState.players){const old=prev.players.find(x=>x.id===p.id);if(old)p.money=old.money;}
 this.holding=!!(events.length||changes.length);const wasPending=this.pending;this.pending=false;
 const settle=this.short?0:1050,depart=this.short?0:1450,arrive=this.short?0:2050;
 if(rolled){this.busyUntil=Date.now()+arrive;this.spinDice();if(!wasPending){this.showStage();this.sound?.play(this.short?'land':'roll');}this.later(()=>{clearInterval(this.spin);this.spin=null;this.drawDice(state.dice);this.settleStage(state.dice);this.sound?.play('land');},settle);this.later(()=>{this.stage?.remove();this.stage=null;},depart);}else if(!this.spin)this.drawDice(state.dice);
 for(const p of state.players){const old=prev.players.find(x=>x.id===p.id);if(old&&old.position!==p.position)this.later(()=>this.travel(old,p,rolled?state.dice[0]+state.dice[1]:null),rolled?depart:0);}
 const outcome=()=>{this.displayState=state;this.milestones(prev,state);const latest=logs.filter(x=>!cardLine.test(x)).at(-1);if(latest)this.announce(latest);if(changes.length)this.payment(changes,()=>this.finish());else this.finish();this.onReady();};
 const showCard=i=>{if(i>=events.length){outcome();return;}const e=events[i];this.card(e.text,e.type,e.title,()=>showCard(i+1));};
 this.later(()=>showCard(0),rolled?arrive:0);
 }
 payment(changes,done){
 const dialog=document.createElement('dialog');dialog.className='payment-sheet';this.receipt=dialog;
 const title=document.createElement('h2');title.textContent='旅のお会計';dialog.append(title);
 for(const {player,before,delta} of changes){this.money(player,delta);const row=document.createElement('p');row.className=delta>0?'income-row':'payment-row';const name=document.createElement('strong');name.textContent=player.name+' · '+(delta>0?'収入':'支払い');const amount=document.createElement('b');amount.textContent=(delta>0?'+':'−')+euro(delta);const balance=document.createElement('small');balance.textContent=euro(before)+' → '+euro(player.money);row.append(name,amount,balance);dialog.append(row);}
 const confirm=document.createElement('button');confirm.className='payment-confirm';confirm.textContent='確認して次へ';let closed=false;confirm.onclick=()=>{if(closed)return;closed=true;dialog.close();dialog.remove();this.receipt=null;done();};dialog.addEventListener('cancel',e=>e.preventDefault());dialog.append(confirm);document.body.append(dialog);dialog.showModal();confirm.focus();
 }

 announce(text){document.querySelector('#game .journey-event')?.remove();const event=document.createElement('p');event.className='journey-event';event.textContent=text;event.setAttribute('role','status');const actions=document.getElementById('actions');if(actions)actions.after(event);else this.layer.append(event);this.transients.add(event);this.later(()=>{event.remove();this.transients.delete(event);},4500);}
 money(player,delta){this.sound?.play(delta>0?'income':'payment');const panel=[...document.querySelectorAll('.player[data-player-id]')].find(x=>x.dataset.playerId===player.id);if(!panel)return;const badge=document.createElement('span');badge.className='money-flight '+(delta>0?'positive':'negative');badge.textContent=(delta>0?'+':'−')+euro(delta);badge.setAttribute('aria-label',player.name+(delta>0?' の収入 ':' の支払い ')+euro(delta));const rect=panel.getBoundingClientRect();Object.assign(badge.style,{position:'fixed',left:Math.max(8,Math.min(innerWidth-115,rect.left+rect.width/2-45))+'px',top:Math.max(12,Math.min(innerHeight-80,rect.top+20))+'px',pointerEvents:'none',zIndex:100});document.body.append(badge);this.transients.add(badge);if(!this.short)badge.animate([{opacity:0,transform:'translateY(12px) scale(.8)'},{opacity:1,transform:'translateY(0) scale(1.1)',offset:.2},{opacity:1,offset:.75},{opacity:0,transform:'translateY(-38px)'}],{duration:1800,fill:'forwards'});this.later(()=>{badge.remove();this.transients.delete(badge);},1900);}
 travel(old,p,steps){if(this.short)return;const tiles=[...document.querySelectorAll('[data-tile-id]')],rect=id=>tiles.find(t=>Number(t.dataset.tileId)===id)?.getBoundingClientRect();const start=rect(old.position);if(!start||!start.width)return;this.flights.get(p.id)?.remove();const dot=document.createElement('span');dot.className='traveler-flight';dot.textContent='●';dot.setAttribute('aria-hidden','true');const token=[...document.querySelectorAll('.token[data-player-id]')].find(t=>t.dataset.playerId===p.id);dot.style.setProperty('--player',token?.style.getPropertyValue('--player')||'#dc915a');Object.assign(dot.style,{position:'fixed',left:'0',top:'0',pointerEvents:'none',zIndex:90});document.body.append(dot);this.flights.set(p.id,dot);const direct=steps&&((old.position+steps)%40===p.position);const path=direct?Array.from({length:steps+1},(_,i)=>(old.position+i)%40):[old.position,p.position];path.forEach((_,i)=>this.later(()=>this.sound?.play('step'),i*(Math.min(550,path.length*70)/path.length)));const frames=path.map(id=>rect(id)).filter(Boolean).map(r=>({transform:`translate(${r.left+r.width/2-8}px,${r.top+r.height/2-8}px)`}));dot.animate(frames,{duration:Math.min(550,path.length*70),easing:'ease-in-out',fill:'both'}).onfinish=()=>{dot.remove();if(this.flights.get(p.id)===dot)this.flights.delete(p.id);};}
 card(text,type='chance',title='',done=()=>{}){this.layer.querySelector('.journey-card')?.remove();const card=document.createElement('button');card.type='button';card.className='journey-card'+(type==='chest'?' letter-card':'');card.dataset.cardType=type;const kicker=document.createElement('small');kicker.textContent=type==='chest'?'LETTER / 旅人の手紙':'CHANCE / 旅のチャンス';const content=document.createElement('strong');content.textContent=type==='chest'?'届いた手紙を開く':'チャンスカードをめくる';const hint=document.createElement('span');hint.textContent='タップで結果を見る';card.append(kicker,content,hint);const reveal=()=>{if(!card.isConnected)return;if(!card.classList.contains('revealed'))this.sound?.play('card');card.classList.add('revealed');content.textContent=(title?title+'：':'')+text;hint.textContent='タップして効果を確認';card.onclick=()=>{card.remove();done();};};card.onclick=reveal;this.layer.append(card);card.focus();}
}
